if (useTvp) {
    request.input(paramName, tvp);
    const tvpAlias = this.getNextTvpAlias();
    const tvpParameterName = buildParameterName(paramName);
    const useExistsStatement = (operatorStrategy === 'exists' && (operator === 'IN' || operator === 'NOT IN')) || (operatorStrategy === 'innerJoin' && operator === 'NOT IN');

    // Generate statement based on strategy
    if (operatorStrategy === 'innerJoin' && operator === 'IN') {
        statement = `INNER JOIN ${tvpParameterName} AS ${tvpAlias} ON ${fieldName} = ${tvpAlias}.${tvpColumnName}`;
    } else if (useExistsStatement) {
        // For NOT IN with INNER JOIN, use NOT EXISTS instead of a join.
        const existsOperator = operator === 'NOT IN' ? 'NOT EXISTS' : 'EXISTS';
        statement = `${existsOperator} (SELECT 1 FROM ${tvpParameterName} AS ${tvpAlias} WHERE ${fieldName} = ${tvpAlias}.${tvpColumnName})`;
    } else {
        // Default to IN/NOT IN operator
        statement = `${fieldName} ${operator} (SELECT ${tvpColumnName} FROM ${tvpParameterName})`;
    }

    return { paramNames: [paramName], values: [tvp], statement, alias: tvpAlias };
}

